tools.example:
model.component("comp1").physics().create("ewfd", "ElectromagneticWavesFrequencyDomain", "geom1");
model.component("comp1").physics("ewfd").prop("BackgroundField").set("SolveFor", "scatteredField");
model.study("std1").create("wave", "Wavelength");
model.study("std1").feature("wave").set("plist", "range(400,10,800)");
model.study("std1").feature("wave").set("punit", "nm");
// Application Libraries: Wave_Optics_Module/Optical_Scattering/scattering_nanosphere, Wave_Optics_Module/Applications/plasmonic_wire_grating

model.component("comp1").physics().create("ewt", "ElectromagneticWavesTransient", "geom1");
model.component("comp1").physics("ewt").prop("components").set("components", "outofplane");
// Bragg reflector excited by a pulse, then Time to Frequency FFT: Wave_Optics_Module/Couplers_Filters_and_Mirrors/time_to_frequency_fft_distributed_bragg_reflector; Wave_Optics_Module/Gratings_and_Metamaterials/drude_lorentz_media

model.component("comp1").physics("ewte").create("bf1", "BackgroundField", 3);
model.component("comp1").physics("ewte").feature("bf1").selection().all();
// modulated Gaussian pulse along +x, polarized in z, f0 = 1.5 GHz; Application Library: RF_Module/Scattering_and_RCS/rcs_time_explicit

model.component("comp1").physics("ewte").create("ffd1", "FarFieldDomain", 3);
model.study("std1").create("tffft", "TimeToFreqFFT");
// Application Library: RF_Module/Scattering_and_RCS/rcs_time_explicit

model.component("comp1").physics("temw").create("lport1", "LumpedPort", 2);
model.component("comp1").physics("temw").feature("lport1").set("PortType", "Uniform");
model.component("comp1").physics("temw").feature("lport1").set("V0", "V0(t)");
// crosstalk between microstrips: temw.Vport_2..4 versus t; Application Libraries: RF_Module/EMI_EMC_Applications/microstrip_line_crosstalk, RF_Module/ESD_and_Lightning_Surge/esd_test_pcb

model.component("comp1").physics("temw").feature("wee2").set("DisplacementFieldModel", "DrudeLorentzDispersionModel");
model.component("comp1").physics("temw").feature("wee2").create("dlp1", "DrudeLorentzPolarization", 2);
// Application Libraries: RF_Module/Tutorials/drude_lorentz_media, Wave_Optics_Module/Gratings_and_Metamaterials/drude_lorentz_media

model.component("comp1").physics("temw").create("sctr1", "Scattering", 2);
model.component("comp1").physics("temw").feature("sctr1").set("IncidentField", "EField");
// Application Libraries: RF_Module/EMI_EMC_Applications/microstrip_line_crosstalk, Wave_Optics_Module/Couplers_Filters_and_Mirrors/time_to_frequency_fft_distributed_bragg_reflector

model.component("comp1").physics().create("ebem", "ElectromagneticWavesBEM", "geom1");
model.component("comp1").physics("ebem").prop("BackgroundField").set("SolveFor", "scatteredField");
model.component("comp1").physics("ebem").prop("BackgroundField").set("WaveType", "ElectricPointDipole");
// Application Library: Wave_Optics_Module/Optical_Scattering/optical_yagi_uda_antenna

model.component("comp1").multiphysics().create("elfc1", "ElectricFieldCoupling", 2);
model.component("comp1").multiphysics("elfc1").selection().all();
// Application Library: RF_Module/Antennas/microstrip_patch_antenna_fem_bem

model.component("comp1").physics("ewbe").prop("WaveVector").set("dirCount", "UniDirectionality");
model.component("comp1").physics("ewbe").prop("WaveVector").set("k1", new String[]{"ewbe.beta_1", "0", "0"});
model.component("comp1").physics("ewbe").prop("MeshControl").set("MeshType", "Swept");
// Application Libraries: Wave_Optics_Module/Couplers_Filters_and_Mirrors/directional_coupler, Wave_Optics_Module/Beam_Propagation/brewster_interface (user-defined phase), Wave_Optics_Module/Waveguides/tapered_waveguide

model.component("comp1").physics("ewbe").create("mbc1", "MatchedBoundaryCondition", 1);
model.component("comp1").physics("ewbe").feature("mbc1").set("IncidentField", "GaussianBeam");
// Application Libraries: Wave_Optics_Module/Beam_Propagation/brewster_interface, Wave_Optics_Module/Waveguides/total_internal_reflection, Wave_Optics_Module/Applications/polarizing_beam_splitter

model.component("comp1").physics("ewfd").create("csc1", "CrossSectionCalculation", 3);
model.component("comp1").physics("ewfd").feature("csc1").selection().named("particle");
// Global plot of ewfd.sigmaSca, ewfd.sigmaAbs, ewfd.sigmaExt versus wavelength; Application Libraries: Wave_Optics_Module/Optical_Scattering/scattering_nanosphere, scatterer_on_substrate

model.component("comp1").multiphysics().create("emh1", "ElectromagneticHeating", 3);
model.component("comp1").multiphysics("emh1").set("EMHeat_physics", "emw");
model.component("comp1").multiphysics("emh1").set("Heat_physics", "ht");
model.component("comp1").multiphysics("emh1").selection().all();
// Application Libraries: RF_Module/Microwave_Heating/microwave_oven, rf_heating, sar_in_human_head, conical_dielectric_probe

model.study("std1").create("ftrans", "FrequencyTransient");
model.study("std1").feature("ftrans").set("freq", "1[MHz]");
model.study("std1").feature("ftrans").set("tlist", "range(0,15,300)");
// Application Libraries: RF_Module/Microwave_Heating/rf_heating (both steps), RF_Module/Microwave_Heating/rotating_microwave_oven, Wave_Optics_Module/Couplers_Filters_and_Mirrors/sesam_laser_heating

model.study("std1").create("wave", "Wavelength");
model.study("std1").feature("wave").set("plist", "range(400,5,800)");
model.study("std1").feature("wave").set("punit", "nm");
// Application Libraries: Wave_Optics_Module/Applications/polarizing_beam_splitter, Wave_Optics_Module/Couplers_Filters_and_Mirrors/enhanced_mems_mirror_coating, Wave_Optics_Module/Gratings_and_Metamaterials/hexagonal_grating

model.component("comp1").multiphysics().create("rhs1", "RayHeatSource", 3);
model.component("comp1").multiphysics("rhs1").set("RayHeatSource_physics", "gop");
model.component("comp1").multiphysics("rhs1").set("RayHeatDestination_physics", "ht");
model.study("std1").create("bcrt", "BidirectionallyCoupledRayTracing");
model.study("std1").feature("bcrt").set("timestepspec", "specifylength");
// Application Libraries: Ray_Optics_Module/Structural_Thermal_Optical_Performance_Analysis/thermally_induced_focal_shift, petzval_lens_stop_analysis, newtonian_telescope_structural_analysis

model.component("comp1").physics("tl").create("iw1", "IncomingWave", 0);
model.component("comp1").physics("tl").feature("iw1").selection().set(new int[]{1});
model.component("comp1").physics("tl").create("ab1", "AbsorbingBoundary", 0);
model.component("comp1").physics("tl").feature("ab1").selection().set(new int[]{2});

model.component("comp1").physics("tl").create("lport1", "LumpedPort", 0);
model.component("comp1").physics("tl").feature("lport1").set("PortExcitation", "on");
model.component("comp1").physics("tl").prop("PortSweepSettings").set("useSweep", true);
// Application Library: RF_Module/Couplers_and_Power_Dividers/transmission_line_butler
